def _ensure_numeric(data: T_Xarray) -> T_Xarray:
    """Converts all datetime64 variables to float64

    Parameters
    ----------
    data : DataArray or Dataset
        Variables with possible datetime dtypes.

    Returns
    -------
    DataArray or Dataset
        Variables with datetime64 dtypes converted to float64.
    """
    from .dataset import Dataset

    def to_floatable(x: DataArray) -> DataArray:
        if x.dtype.kind in "mM":
            # For a 1D DataArray with a datetime/timedelta dimension coordinate,
            # use the coordinate values as the data to be consistent with
            # how polyfit extracts x-values via get_clean_interp_index.
            if len(x.dims) == 1:
                dim = x.dims[0]
                if dim in x.coords and x.coords[dim].dtype.kind in "mM":
                    x = x.copy(data=x.coords[dim].data)
            if x.dtype.kind == "M":
                return x.copy(
                    data=datetime_to_numeric(
                        x.data,
                        offset=np.datetime64("1970-01-01"),
                        datetime_unit="ns",
                    ),
                )
            else:
                return x.copy(
                    data=datetime_to_numeric(x.data, datetime_unit="ns"),
                )
        return x

    if isinstance(data, Dataset):
        return data.map(to_floatable)
    else:
        return to_floatable(data)


